## Mando dibujado para sensor_msgs/Joy: dos sticks y una fila de botones.
@export var pares_sticks: Array[Vector2i] = [Vector2i(0, 1), Vector2i(3, 4)]   # índices (x, y) en axes
@export var invertir_x := true		   # convención joy: izquierda = +1; en pantalla, izquierda = -x
var _ejes = []						   # sin tipo: rclgd/ros2_vita dan Packed*Array (H25)
var _botones = []

func _init() -> void:
	topic = "/joy"
	tipo = "sensor_msgs/msg/Joy"
	hz_dibujo = 20.0

func _recibir(m: RosMsg) -> void:
	_ejes = m.axes
	_botones = m.buttons

func _eje(i: int) -> float:
	return _ejes[i] if i < _ejes.size() else 0.0

func _draw() -> void:
	var base := Color.DIM_GRAY if caducado() else Color(0.9, 0.9, 0.9)
	var radio := size.y * 0.3
	for k in pares_sticks.size():
		var c := Vector2(size.x * (0.25 + 0.5 * k), size.y * 0.4)
		draw_arc(c, radio, 0.0, TAU, 24, base, -1.0)
		var sx := _eje(pares_sticks[k].x) * (-1.0 if invertir_x else 1.0)
		draw_circle(c + Vector2(sx, -_eje(pares_sticks[k].y)) * radio, radio * 0.25, Color(1.0, 0.75, 0.2))
	var paso := size.x / maxf(1.0, _botones.size())
	for b in _botones.size():
		var on: bool = _botones[b] != 0
		draw_rect(Rect2(b * paso + 1, size.y - 14, paso - 2, 12), Color(0.3, 1.0, 0.4) if on else base, on)

