## Icono de batería para sensor_msgs/BatteryState: relleno = percentage, color por salud y umbral.
const ESTADO := ["?", "cargando", "descargando", "sin cargar", "llena"]   # POWER_SUPPLY_STATUS_*
const SALUD_MALA := [2, 3, 4, 5, 6, 7, 8]  # OVERHEAT … SAFETY_TIMER_EXPIRE
@export var umbral_bajo := 0.2
var _pct := NAN
var _txt := ""
var _alarma := false

func _init() -> void:
	topic = "/battery_state"
	tipo = "sensor_msgs/msg/BatteryState"
	caducidad_s = 15.0				   # bateria.gd publica a 1 Hz (0,2 Hz en la Vita)

func _recibir(m: RosMsg) -> void:
	_pct = m.percentage				  # 0..1; NaN si no se mide
	if is_nan(_pct) and m.capacity > 0.0:
		_pct = m.charge / m.capacity
	var st := int(m.power_supply_status)
	_alarma = int(m.power_supply_health) in SALUD_MALA or (not is_nan(_pct) and _pct < umbral_bajo)
	_txt = "%.1f V %+.1f A %s" % [m.voltage, m.current, ESTADO[st] if st < ESTADO.size() else "?"]

func _draw() -> void:
	var cuerpo := Rect2(2, 2, size.x - 10, size.y - 4)
	draw_rect(cuerpo, Color.WHITE, false, 2.0)
	draw_rect(Rect2(size.x - 8, size.y * 0.3, 6, size.y * 0.4), Color.WHITE)
	if is_nan(_pct):
		return
	var c := Color.DIM_GRAY if caducado() else (Color8(178, 23, 46) if _alarma else Color8(85, 178, 76))
	draw_rect(Rect2(5, 5, (cuerpo.size.x - 6) * clampf(_pct, 0.0, 1.0), cuerpo.size.y - 6), c)
	draw_string(get_theme_default_font(), Vector2(8, size.y - 8), "%d %%  %s" % [roundi(_pct * 100.0), _txt],
			HORIZONTAL_ALIGNMENT_LEFT, size.x - 16, 12)

