## medidor.gd: un float64 con unidades (Temperature, FluidPressure, Illuminance, RelativeHumidity).
## Barra con umbrales + valor + sparkline de las últimas N muestras (una polilínea = 1 comando, H17).
@export var campo := "temperature"	   # fluid_pressure | illuminance | relative_humidity
@export var escala := 1.0				# 0.01 Pa->hPa, 100 humedad 0..1->%
@export var unidad := "°C"
@export var minimo := -10.0
@export var maximo := 60.0
@export var aviso := 45.0				# amarillo desde aquí; rojo desde maximo
@export var muestras := 60
var _v := NAN
var _serie := PackedFloat32Array()

func _recibir(m: RosMsg) -> void:
	_v = float(m.get_member(campo)) * escala
	_serie.append(_v)
	if _serie.size() > muestras:
		_serie.remove_at(0)

func _color() -> Color:
	if caducado():
		return Color.DIM_GRAY
	return Color8(85, 178, 76) if _v < aviso else (Color8(222, 213, 17) if _v < maximo else Color8(178, 23, 46))

func _draw() -> void:
	draw_rect(Rect2(Vector2.ZERO, size), Color(0.08, 0.09, 0.12))
	if is_nan(_v):
		return
	var c := _color()
	draw_rect(Rect2(0, size.y - 6, size.x * clampf(inverse_lerp(minimo, maximo, _v), 0.0, 1.0), 6), c)
	draw_string(get_theme_default_font(), Vector2(4, 14), "%.1f %s" % [_v, unidad], HORIZONTAL_ALIGNMENT_LEFT, -1, 13, c)
	var pts := PackedVector2Array()
	for i in _serie.size():
		var f := clampf(inverse_lerp(minimo, maximo, _serie[i]), 0.0, 1.0)
		pts.append(Vector2(size.x * i / maxf(1.0, muestras - 1), 18.0 + (size.y - 26.0) * (1.0 - f)))
	if pts.size() > 1:
		draw_polyline(pts, c, -1.0)	  # -1 = línea fina, un solo comando de lienzo

