## Tabla tipo rqt_robot_monitor para diagnostic_msgs/DiagnosticArray: una fila por estado, peores arriba.
const COLOR := [Color8(85, 178, 76), Color8(222, 213, 17), Color8(178, 23, 46), Color8(40, 23, 176)]
const TEXTO := ["OK", "WARN", "ERROR", "STALE"]
@export var max_filas := 12			  # 12 filas x ~40 glifos = ~500 quads (docs/31 §5.3)
@export var caducidad_fila_s := 10.0	 # rqt_robot_monitor: STALE a los 10 s sin noticias
@export var solo_problemas := false	  # filtro «Warnings/Errors» de rqt
var _filas := {}						 # nombre -> [nivel, mensaje, edad_s]

func _init() -> void:
	topic = "/diagnostics_agg"		   # o /diagnostics sin agregador
	tipo = "diagnostic_msgs/msg/DiagnosticArray"
	best_effort = false				  # >= 3 estados ya pasan de 488 B; fiable hasta ~7,5 KiB a 1 Hz
	caducidad_s = 10.0

func _recibir(m: RosMsg) -> void:
	for st in m.status:
		_filas[str(st.name)] = [int(st.level), str(st.message), 0.0]

func _process(dt: float) -> void:
	for k in _filas:
		_filas[k][2] += dt
	super(dt)

func _draw() -> void:
	var fuente := get_theme_default_font()
	var claves := _filas.keys()
	claves.sort_custom(func(a, b): return _filas[a][0] > _filas[b][0])
	var y := 14.0
	for k in claves.slice(0, max_filas):
		var nivel: int = 3 if _filas[k][2] > caducidad_fila_s else clampi(_filas[k][0], 0, 3)
		if solo_problemas and nivel == 0:
			continue
		draw_rect(Rect2(2, y - 10, 10, 10), COLOR[nivel])
		draw_string(fuente, Vector2(16, y), "%s  %s: %s" % [TEXTO[nivel], k, _filas[k][1]],
				HORIZONTAL_ALIGNMENT_LEFT, size.x - 18, 12)
		y += 14.0

