## Consola tipo rqt_console para rcl_interfaces/msg/Log (/rosout): anillo de N líneas, filtro por nivel y nodo.
const COLORES := {10: Color.GRAY, 20: Color.WHITE, 30: Color8(222, 213, 17), 40: Color8(230, 80, 80), 50: Color.MAGENTA}
const LETRA := {10: "D", 20: "I", 30: "W", 40: "E", 50: "F"}
@export var nivel_minimo := 20		   # Log.INFO; en la Vita el relay ya deja solo >= WARN
@export var filtro_nodo := ""			# subcadena de Log.name ("" = todos)
@export var max_lineas := 10			 # 10 x ~60 glifos = ~600 quads: solo al llegar (H16)
var _lineas: Array = []				  # [nivel, texto]
var pausada := false					 # «Pause» de rqt_console (botón/tecla en la HMI)

func _init() -> void:
	topic = "/rosout"
	tipo = "rcl_interfaces/msg/Log"
	best_effort = false				  # /rosout es RELIABLE + TRANSIENT_LOCAL; aquí VOLATILE: sin historial
	caducidad_s = INF					# silencio en /rosout no es un fallo

func _recibir(m: RosMsg) -> void:
	var nivel := int(m.level)
	if pausada or nivel < nivel_minimo or (filtro_nodo != "" and not filtro_nodo in str(m.name)):
		return
	var t = m.stamp
	_lineas.append([nivel, "[%s] %d.%03d %s: %s" % [LETRA.get(nivel, "?"), t.sec % 100000,
			t.nanosec / 1000000, m.name, m.msg]])
	if _lineas.size() > max_lineas:
		_lineas.pop_front()

func _draw() -> void:
	draw_rect(Rect2(Vector2.ZERO, size), Color(0, 0, 0, 0.6))
	var fuente := get_theme_default_font()
	for i in _lineas.size():
		var l: Array = _lineas[i]
		draw_string(fuente, Vector2(4, 14 + 13 * i), l[1], HORIZONTAL_ALIGNMENT_LEFT, size.x - 8, 11,
				COLORES.get(l[0], Color.WHITE))

