## Fila de estado de un nodo gestionado: lifecycle_msgs/TransitionEvent en <nodo>/transition_event.
const NOMBRE := {0: "desconocido", 1: "sin configurar", 2: "inactivo", 3: "activo", 4: "finalizado",
	10: "configurando", 11: "limpiando", 12: "apagando", 13: "activando", 14: "desactivando", 15: "ERROR"}
@export var nodo_gestionado := "/controller_server"
var _estado := 0						 # 0 hasta el primer evento (el estado inicial es un servicio)
var _transicion := ""

func _init() -> void:
	tipo = "lifecycle_msgs/msg/TransitionEvent"
	best_effort = false				  # solo hay mensaje al cambiar: no se puede perder (65 B)

func _ready() -> void:
	topic = nodo_gestionado + "/transition_event"   # antes de conectar()

func caducado() -> bool:
	return false						 # evento, no flujo: el silencio no es fallo

func _recibir(m: RosMsg) -> void:
	_estado = int(m.goal_state.id)
	_transicion = str(m.transition.label)

func _color() -> Color:
	match _estado:
		3: return Color8(85, 178, 76)
		2, 10, 13, 14: return Color8(222, 213, 17)
		15: return Color8(178, 23, 46)
	return Color.DIM_GRAY

func _draw() -> void:
	draw_rect(Rect2(2, 2, 10, 10), _color())
	draw_string(get_theme_default_font(), Vector2(16, 12), "%s: %s (%s)" % [nodo_gestionado,
			NOMBRE.get(_estado, "?"), _transicion], HORIZONTAL_ALIGNMENT_LEFT, size.x - 18, 12)

