## Cajas de vision_msgs/Detection2DArray encima del TextureRect de la cámara (mismo tamaño y posición).
@export var ancho_imagen := 640.0		# CameraInfo.width de la imagen ORIGINAL (no la del relay)
@export var alto_imagen := 480.0
@export var umbral_score := 0.3
var _cajas: Array = []				   # [Rect2 en píxeles de imagen, etiqueta, score]

func _init() -> void:
	tipo = "vision_msgs/msg/Detection2DArray"
	best_effort = false				  # 1 detección = 481 B y 3 = 1 377 B: no caben en BE

func _recibir(m: RosMsg) -> void:
	_cajas.clear()
	for d in m.detections:
		var etiqueta := str(d.id)
		var score := 1.0
		if d.results.size() > 0:		 # la hipótesis de más score suele ir primero [I]
			etiqueta = str(d.results[0].hypothesis.class_id)
			score = float(d.results[0].hypothesis.score)
		if score >= umbral_score:
			var b = d.bbox			   # BoundingBox2D: center (Pose2D) + size_x/size_y; theta se ignora
			var s := Vector2(b.size_x, b.size_y)
			_cajas.append([Rect2(Vector2(b.center.position.x, b.center.position.y) - s * 0.5, s), etiqueta, score])

func _draw() -> void:
	var k := size / Vector2(ancho_imagen, alto_imagen)
	var fuente := get_theme_default_font()
	for caja in _cajas:
		var r: Rect2 = caja[0]
		var col := Color.DIM_GRAY if caducado() else Color.from_hsv(float(absi(hash(caja[1])) % 360) / 360.0, 0.8, 1.0)
		draw_rect(Rect2(r.position * k, r.size * k), col, false, 2.0)
		draw_string(fuente, r.position * k + Vector2(2, -2), "%s %d%%" % [caja[1], roundi(caja[2] * 100.0)],
				HORIZONTAL_ALIGNMENT_LEFT, -1, 11, col)

extends "res://comun/hmi/widget_hud.gd"
## Cajas de vision_msgs/Detection3DArray: 12 aristas por caja proyectadas al HUD con UNA draw_multiline
## (H17). Igual en PC y Vita: en la Vita no hay líneas 3D sin shaders (docs/31 §2.2).
@export var camara: Camera3D
@export var marco_fijo: Node3D		   # nodo de la escena alineado con header.frame_id (p. ej. «map»)
const ARISTAS := [0,1, 2,3, 4,5, 6,7, 0,2, 1,3, 4,6, 5,7, 0,4, 1,5, 2,6, 3,7]
var _esquinas: Array = []				# PackedVector3Array(8) por caja, en ejes Godot del marco

func _init() -> void:
	tipo = "vision_msgs/msg/Detection3DArray"
	best_effort = false				  # 1 detección = 489 B (> 488)

func _recibir(m: RosMsg) -> void:
	_esquinas.clear()
	for d in m.detections:
		var c = d.bbox.center			# BoundingBox3D: center (Pose) + size (Vector3)
		var q := rclgd.ros_to_godot_quat(Quaternion(c.orientation.x, c.orientation.y, c.orientation.z, c.orientation.w))
		var t := Transform3D(Basis(q), rclgd.ros_to_godot_vector(Vector3(c.position.x, c.position.y, c.position.z)))
		var h := rclgd.ros_to_godot_vector(Vector3(d.bbox.size.x, d.bbox.size.y, d.bbox.size.z)).abs() * 0.5
		var e := PackedVector3Array()
		for i in 8:
			e.append(t * Vector3(h.x * (1 if i & 1 else -1), h.y * (1 if i & 2 else -1), h.z * (1 if i & 4 else -1)))
		_esquinas.append(e)

func _process(dt: float) -> void:
	super(dt)
	queue_redraw()					   # la cámara se mueve: reproyectar (8 unproject por caja)

func _draw() -> void:
	var segs := PackedVector2Array()
	for e in _esquinas:
		for i in range(0, ARISTAS.size(), 2):
			var a: Vector3 = marco_fijo.global_transform * e[ARISTAS[i]]
			var b: Vector3 = marco_fijo.global_transform * e[ARISTAS[i + 1]]
			if not (camara.is_position_behind(a) or camara.is_position_behind(b)):
				segs.append_array([camara.unproject_position(a), camara.unproject_position(b)])
	if segs.size() >= 2:
		draw_multiline(segs, Color.DIM_GRAY if caducado() else Color(0.2, 1.0, 0.6), -1.0)

