## Fantasma de trajectory_msgs/JointTrajectory: copia del robot horneado (ADR 0009) que recorre los puntos
## en bucle según time_from_start, interpolando en lineal. Robot con set_joints() (urdf_robot.gd:80).
@export var escena_robot: PackedScene	# en el PC con material translúcido; en la Vita, ver ficha
@export var topic := "/arm_controller/joint_trajectory"
@export var velocidad := 1.0
var nodo: RosNode
var _sub: RosSubscriber
var _fantasma: Node3D
var _nombres := PackedStringArray()
var _t := PackedFloat32Array()		   # time_from_start en s
var _q: Array = []					   # PackedFloat64Array por punto
var _reloj := 0.0

func conectar(n: RosNode) -> void:
	nodo = n
	_fantasma = escena_robot.instantiate()
	add_child(_fantasma)
	_sub = nodo.create_subscription(topic, "trajectory_msgs/msg/JointTrajectory", _on_tray)

func _on_tray(m: RosMsg) -> void:
	_nombres = m.joint_names
	_t.clear()
	_q.clear()
	for p in m.points:
		_t.append(p.time_from_start.sec + p.time_from_start.nanosec * 1e-9)
		_q.append(p.positions)
	_reloj = 0.0

func _process(dt: float) -> void:
	if _t.is_empty():
		return
	_reloj = fmod(_reloj + dt * velocidad, _t[-1] + 0.5)   # 0,5 s de pausa al final del bucle
	var i := clampi(_t.bsearch(_reloj), 1, _t.size() - 1) if _t.size() > 1 else 0
	var q: PackedFloat64Array = _q[i].duplicate()
	if i > 0:
		var a := clampf(inverse_lerp(_t[i - 1], _t[i], _reloj), 0.0, 1.0)
		for j in mini(q.size(), _q[i - 1].size()):
			q[j] = lerpf(_q[i - 1][j], q[j], a)
	_fantasma.call("set_joints", _nombres, q)

