## Panel de control_msgs/JointTrajectoryControllerState: por junta, real (barra azul), referencia (marca
## naranja) y |error| en rojo si pasa la tolerancia. El fantasma 3D de la referencia usa la ficha JointTrajectory.
@export var limite_rad := PI
@export var tolerancia := 0.05
var _nombres := PackedStringArray()
var _ref := PackedFloat64Array()
var _real := PackedFloat64Array()
var _err := PackedFloat64Array()

func _init() -> void:
	topic = "/joint_trajectory_controller/controller_state"
	tipo = "control_msgs/msg/JointTrajectoryControllerState"
	best_effort = false				  # 7 juntas = 1 340 B (fiable, <= 5 Hz); estado_controlador.gd:13

func _recibir(m: RosMsg) -> void:
	_nombres = m.joint_names
	_ref = m.get_member("reference").positions   # `reference` choca con RefCounted.reference()
	_real = m.feedback.positions
	_err = m.error.positions

func _x(v: float, cx: float, w: float) -> float:
	return cx + w * 0.5 * clampf(v / limite_rad, -1.0, 1.0)

func _draw() -> void:
	var fuente := get_theme_default_font()
	var cx := size.x * 0.7
	var w := size.x * 0.58
	for i in mini(_nombres.size(), mini(_ref.size(), _real.size())):
		var y := 2.0 + i * 14.0
		draw_rect(Rect2(cx - w * 0.5, y, w, 11), Color(0.2, 0.2, 0.25))
		draw_rect(Rect2(minf(cx, _x(_real[i], cx, w)), y + 2, absf(_x(_real[i], cx, w) - cx), 7), Color(0.3, 0.7, 1.0))
		var xr := _x(_ref[i], cx, w)
		draw_rect(Rect2(xr - 1, y, 2, 11), Color(1.0, 0.75, 0.2))
		var e := absf(_err[i]) if i < _err.size() else 0.0
		draw_string(fuente, Vector2(2, y + 10), "%s %.3f" % [_nombres[i], e], HORIZONTAL_ALIGNMENT_LEFT,
				size.x * 0.4 - 4, 11, Color.WHITE if e < tolerancia else Color8(230, 80, 80))

