## Plan (/plan o /vita/path_compacto) frente al rastro real (/odom o /vita/pose2d); planta como g6-hmi.
@export var escala := 80.0			   # px/m (g6-hmi/main.gd:13)
@export var rastro_max := 600
var _subs: Array = []				   # guardar las suscripciones (RefCounted)
var _plan := PackedVector2Array()
var _real := PackedVector2Array()

func conectar(n: RosNode, compacto: bool) -> void:
	var plan := ["/vita/path_compacto", "std_msgs/msg/Float32MultiArray"] if compacto else ["/plan", "nav_msgs/msg/Path"]
	var pose := ["/vita/pose2d", "std_msgs/msg/Float32MultiArray"] if compacto else ["/odom", "nav_msgs/msg/Odometry"]
	_subs = [n.create_subscription(plan[0], plan[1], _on_plan), n.create_subscription(pose[0], pose[1], _on_pose)]

func _a_pantalla(x: float, y: float) -> Vector2:
	return Vector2(x, -y) * escala	   # ROS (x delante, y izquierda) -> lienzo (y abajo)

func _on_plan(m: RosMsg) -> void:
	_plan.clear()
	if m.get_ros_interface_name() == "nav_msgs/msg/Path":
		for ps in m.poses:
			_plan.append(_a_pantalla(ps.pose.position.x, ps.pose.position.y))
	else:
		var d: PackedFloat32Array = m.data   # [n, x0, y0, …] (docs/27 §2)
		for i in int(d[0]):
			_plan.append(_a_pantalla(d[1 + 2 * i], d[2 + 2 * i]))
	queue_redraw()

func _on_pose(m: RosMsg) -> void:
	var odo := m.get_ros_interface_name() == "nav_msgs/msg/Odometry"
	var p := _a_pantalla(m.pose.pose.position.x, m.pose.pose.position.y) if odo else _a_pantalla(m.data[0], m.data[1])
	if _real.is_empty() or _real[-1].distance_to(p) > 2.0:
		_real.append(p)
		if _real.size() > rastro_max:
			_real.remove_at(0)
		queue_redraw()

func _draw() -> void:
	if _plan.size() > 1: draw_polyline(_plan, Color(0.3, 1.0, 0.4), -1.0)
	if _real.size() > 1: draw_polyline(_real, Color(0.3, 0.7, 1.0), -1.0)

