## herramienta_pose.gd = «Nav2 Goal» (goal_tool.cpp): pulsar = posición, arrastrar = rumbo, soltar = publicar.
## Ratón en PC; táctil de la Vita como ratón (emulate_mouse_from_touch) [I]. «2D Pose Estimate» hereda.
@export var camara: Camera3D
@export var marco_fijo: Node3D		   # nodo de la escena alineado con el frame fijo
@export var frame_fijo := "map"
@export var topic := "goal_pose"		 # relativo, como RViz (goal_tool.cpp:52-53)
@export var tipo := "geometry_msgs/msg/PoseStamped"
var nodo: RosNode
var _pub: RosPublisher
var _inicio = null					   # Vector3 en ejes ROS del punto pulsado, o null
var _yaw := 0.0

func conectar(n: RosNode) -> void:
	nodo = n
	_pub = nodo.create_publisher(topic, tipo)   # QoS por defecto = fiable: bt_navigator/AMCL se suscriben fiables

func _suelo_ros(p: Vector2):
	var g := marco_fijo.global_transform
	var hit = Plane(g.basis.y.normalized(), g.origin).intersects_ray(camara.project_ray_origin(p), camara.project_ray_normal(p))
	return null if hit == null else rclgd.godot_to_ros_vector(g.affine_inverse() * hit)

func _unhandled_input(e: InputEvent) -> void:
	if e is InputEventMouseButton and e.button_index == MOUSE_BUTTON_LEFT:
		if e.pressed:
			_inicio = _suelo_ros(e.position)
		elif _inicio != null:
			_publicar(_inicio, _yaw)
			_inicio = null
	elif e is InputEventMouseMotion and _inicio != null:
		var p = _suelo_ros(e.position)
		if p != null and Vector2(p.x - _inicio.x, p.y - _inicio.y).length() > 0.05:
			_yaw = atan2(p.y - _inicio.y, p.x - _inicio.x)   # pose_tool.cpp:151

func _publicar(p: Vector3, yaw: float) -> void:
	var m := RosMsg.from_type(tipo)
	m.header.frame_id = frame_fijo; m.header.stamp = nodo.now()   # Vita: hora del agente (API_PARITY.md:31)
	m.pose.position.x = p.x; m.pose.position.y = p.y
	m.pose.orientation.z = sin(yaw * 0.5); m.pose.orientation.w = cos(yaw * 0.5)   # pose_tool.cpp:154-161
	_pub.publish(m)

extends Node
## «Publish Point» (point_tool.cpp): al SOLTAR el clic, rayo físico contra la escena (colisiones del
## mundo editable, docs/35) o, si no toca nada, contra el suelo; publica PointStamped en /clicked_point.
@export var camara: Camera3D
@export var marco_fijo: Node3D
@export var frame_fijo := "map"
@export var topic := "/clicked_point"	# point_tool.cpp:60-61
@export var un_solo_clic := true		 # «Single click»: se desactiva tras publicar (point_tool.cpp:65-68)
@export var alcance := 200.0
var nodo: RosNode
var _pub: RosPublisher
var activa := false					  # la HMI la activa con su botón/pestaña

func conectar(n: RosNode) -> void:
	nodo = n
	_pub = nodo.create_publisher(topic, "geometry_msgs/msg/PointStamped")   # 44 B

func _unhandled_input(e: InputEvent) -> void:
	if not (activa and e is InputEventMouseButton and e.button_index == MOUSE_BUTTON_LEFT and not e.pressed):
		return						   # RViz publica en leftUp (point_tool.cpp:111-114)
	var o := camara.project_ray_origin(e.position)
	var fin := o + camara.project_ray_normal(e.position) * alcance
	var hit := camara.get_world_3d().direct_space_state.intersect_ray(PhysicsRayQueryParameters3D.create(o, fin))
	var g := marco_fijo.global_transform
	var punto = hit.get("position", Plane(g.basis.y.normalized(), g.origin).intersects_ray(o, fin - o))
	if punto == null:
		return
	var p := rclgd.godot_to_ros_vector(g.affine_inverse() * punto)
	var m := RosMsg.from_type("geometry_msgs/msg/PointStamped")
	m.header.frame_id = frame_fijo
	m.header.stamp = nodo.now()
	m.point.x = p.x
	m.point.y = p.y
	m.point.z = p.z
	_pub.publish(m)
	activa = not un_solo_clic

extends Node
## Teleop (Foxglove Teleop, rqt_robot_steering, teleop_twist_joy): stick izquierdo de la Vita o flechas del
## PC -> geometry_msgs/Twist a 20 Hz. Hombre muerto = R mantenido (enable_button de teleop_twist_joy) o Mayús.
@export var topic := "/cmd_vel"
@export var v_max := 0.5				 # m/s
@export var w_max := 1.0				 # rad/s
@export var zona_muerta := 0.12		  # g6-hmi/main.gd:19
var nodo: RosNode
var _pub: RosPublisher
var _timer: RosTimer
var _activo := false

func conectar(n: RosNode) -> void:
	nodo = n
	_pub = nodo.create_publisher(topic, "geometry_msgs/msg/Twist")   # fiable por defecto: casa con todos
	_timer = nodo.create_timer(0.05, _tick)

func _eje(a: JoyAxis) -> float:
	var v := Input.get_joy_axis(0, a)
	return 0.0 if absf(v) < zona_muerta else signf(v) * (absf(v) - zona_muerta) / (1.0 - zona_muerta)

func _tick() -> void:
	var hombre_muerto := Input.is_joy_button_pressed(0, JOY_BUTTON_RIGHT_SHOULDER) or Input.is_key_pressed(KEY_SHIFT)
	if not hombre_muerto and not _activo:
		return						   # en reposo, silencio: la puerta del robot para sola (docs/32 §Q5)
	var lin := clampf(-_eje(JOY_AXIS_LEFT_Y) + Input.get_axis("ui_down", "ui_up"), -1.0, 1.0)
	var ang := clampf(-_eje(JOY_AXIS_LEFT_X) + Input.get_axis("ui_right", "ui_left"), -1.0, 1.0)
	var m := RosMsg.from_type("geometry_msgs/msg/Twist")
	if hombre_muerto:
		m.linear.x = lin * v_max + 0.0   # +0.0 evita publicar -0.0 (g6-hmi/main.gd:98)
		m.angular.z = ang * w_max + 0.0
	_pub.publish(m)					  # al soltar sale UN Twist cero y luego silencio
	_activo = hombre_muerto
